use vstd::prelude::*;
use vstd::string::*;

verus! {

fn check_if_last_char_is_a_letter(txt: &str) -> (result: bool)
    ensures
        result == (
            txt.len() > 0 && 
            txt.chars().last().is_ascii_alphabetic() &&
            (txt.len() == 1 || txt.chars().nth(txt.len() - 2).is_space())
        ),
{
    let len = txt.len();
    
    // If string is empty, return false
    if len == 0 {
        return false;
    }
    
    // Get the last character
    let last_char = txt.chars().last();
    
    // Check if last character is ASCII letter
    if !last_char.is_ascii_alphabetic() {
        return false;
    }
    
    // If string has exactly one character, return true
    if len == 1 {
        return true;
    }
    
    // Otherwise, check if the character before last is a space
    let second_last_char = txt.chars().nth(len - 2);
    second_last_char.is_space()
}

} // verus!

